@Override
    public boolean elytraFlightTick(ItemStack stack, LivingEntity entity, int flightTicks) {

        boolean isCreative = Utils.isCreativePlayer(entity);
        boolean simulate = isCreative || flightTicks % energyUseInterval != 0;
        if (!useEnergy(stack, false, simulate)) {
            return false;
        }

        if (entity.isShiftKeyDown() && useEnergy(stack, true, simulate)) {
            stack.getOrCreateTag().remove(NBTTags.TAG_TIME);
            brake(entity);
        } else {
            CompoundTag tag = stack.getOrCreateTag();
            long time = entity.level.getGameTime();
            if (time - tag.getLong(NBTTags.TAG_TIME) <= boostTime) {
                propel(entity);
            } else if (isEmpowered(stack) && useEnergy(stack, true, isCreative)) {
                tag.putLong(NBTTags.TAG_TIME, time);
                propel(entity);
            }
        }

        return true;
    }

@Override
    public void inventoryTick(ItemStack stack, Level world, Entity entity, int slot, boolean selected) {

        if (entity instanceof LivingEntity && !((LivingEntity) entity).isFallFlying()) {
            stack.getOrCreateTag().remove(NBTTags.TAG_TIME);
        }
    }

public boolean boost(ItemStack stack, LivingEntity entity, int time) {

        if (!entity.getItemBySlot(EquipmentSlot.CHEST).canElytraFly(entity)) {
            return false;
        }
        boolean isPlayer = entity instanceof Player;
        boolean isCreative = isPlayer && ((Player) entity).abilities.instabuild;
        if (!useEnergy(stack, getEnergyPerUse(true) * time / energyUseInterval, isCreative)) {
            return false;
        }
        if (!entity.isFallFlying() && isPlayer) {
            ((Player) entity).startFallFlying();
        }
        propel(entity, propelSpeed);
        stack.getOrCreateTag().putLong(NBTTags.TAG_TIME, entity.level.getGameTime());

        return true;
    }

public void propel(LivingEntity entity, double speed) {

        if (entity.isFallFlying()) {
            Vec3 look = entity.getLookAngle();
            Vec3 velocity = entity.getDeltaMovement();
            entity.setDeltaMovement(velocity.add(look.x * speed - velocity.x * 0.5, look.y * speed - velocity.y * 0.5, look.z * speed - velocity.z * 0.5));

            if (entity.level.isClientSide()) {
                entity.level.addParticle(DustParticleOptions.REDSTONE, entity.getX(), entity.getY(), entity.getZ(), 0, 0, 0);
            }
        }
    }

public void brake(LivingEntity entity, double rate) {

        if (entity.isFallFlying()) {
            Vec3 velocity = entity.getDeltaMovement();
            double horzBrake = velocity.x() * velocity.x() + velocity.z() * velocity.z() > 0.16 ? rate : 1;
            double vertBrake = velocity.y() * velocity.y() > 0.2 ? rate : 1;
            entity.setDeltaMovement(velocity.multiply(horzBrake, vertBrake, horzBrake));
        }
    }

default boolean useEnergy(ItemStack stack, int amount, boolean simulate) {

        if (simulate) {
            return true;
        }
        if (hasEnergy(stack, amount)) {
            extractEnergy(stack, amount, false);
            return true;
        }
        return false;
    }

public void dealDamageTo(LivingEntity target) {
        LivingEntity owner = this.getOwner();
        float damage = 4.0F;
        if (this.tickCount >= 14){
            damage = 2.0F;
        }
        if (target.isAlive() && !target.isInvulnerable() && target != owner) {
            if (target.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES)){
                return;
            }
            if (owner == null) {
                boolean flag = target.getType().is(EntityTypeTags.FREEZE_HURTS_EXTRA_TYPES);
                if (flag){
                    damage *= 2.0F;
                }
                if (target.hurt(this.damageSources().freeze(), damage)){
                    target.invulnerableTime = 16;
                }
            } else {
                if (owner instanceof Mob mobOwner) {
                    if (mobOwner instanceof Enemy && target instanceof Enemy) {
                        if (mobOwner.getTarget() != target) {
                            return;
                        }
                    }
                    if (mobOwner instanceof IOwned owned){
                        if (owned.getTrueOwner() != null){
                            if (MobUtil.areAllies(owned.getTrueOwner(), target)){
                                return;
                            }
                        }
                    }
                }
                if (MobUtil.areAllies(owner, target)){
                    return;
                }
                if (owner instanceof Mob) {
                    if (owner.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                        damage = (float) owner.getAttributeValue(Attributes.ATTACK_DAMAGE);
                        if (damage < 1){
                            damage = 1.0F;
                        }
                        if (this.tickCount >= 14){
                            damage /= 2.0F;
                        }
                    }
                } else {
                    damage += this.getExtraDamage();
                }
                DamageSource damageSource = ModDamageSource.iceBouquet(this, owner);
                if (this.isTrap()) {
                    damageSource = ModDamageSource.getDamageSource(this.level, ModDamageSource.ICE_BOUQUET);
                }
                if (target.hurt(damageSource, damage)){
                    target.invulnerableTime = 16;
                    if (owner instanceof Player player) {
                        if (target.isAlive() && this.isSoulEating() && SEHelper.getSoulGiven(target) > 0) {
                            SEHelper.increaseSouls(player, 1);
                        }
                        if (this.isTrap()) {
                            target.lastHurtByPlayer = player;
                            target.lastHurtByPlayerTime = 100;
                        }
                    }
                    if (this.isTrap()) {
                        target.lastHurtByMob = owner;
                        target.lastHurtByMobTimestamp = 100;
                    }
                }
            }
        }
    }

public void tick() {
        super.tick();
        if (this.level.isClientSide) {
            if (this.sentTrapEvent) {
                if (this.animationTicks > 9){
                    --this.animationTicks;
                }
                if (this.getAnimation() < 44){
                    this.setAnimation(this.getAnimation() + 1);
                } else {
                    this.setAnimation(13);
                }
                if (this.lifeTicks <= 14) {
                    --this.lifeTicks;
                }
                if (this.tickCount >= 10) {
                    this.level.addParticle(new MagicSmokeParticleOption(0xb8e5ff, 0x015687, 10 + this.level.getRandom().nextInt(10), 0.2F), this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
                    if (this.level.random.nextInt(24) == 0) {
                        this.level.playLocalSound((double)this.blockPosition().getX() + 0.5D, (double)this.blockPosition().getY() + 0.5D, (double)this.blockPosition().getZ() + 0.5D, SoundEvents.FIRE_AMBIENT, SoundSource.BLOCKS, 1.0F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F, false);
                    }
                }
            }
        } else {
            if (!this.isNoGravity()) {
                MobUtil.moveDownToGround(this);
            }
            if (!this.sentTrapEvent) {
                this.level.broadcastEntityEvent(this, (byte)4);
                this.sentTrapEvent = true;
            }

            if (this.isCenter()) {
                if (!this.playSound) {
                    this.level.broadcastEntityEvent(this, (byte) 5);
                    this.playSound = true;
                }
            }

            if (this.tickCount >= 12){
                if (!this.isCenter()){
                    if (!this.playSound) {
                        this.level.broadcastEntityEvent(this, (byte) 8);
                        this.playSound = true;
                    }
                }
                for(LivingEntity livingentity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())) {
                    this.dealDamageTo(livingentity);
                }
            }

            if (this.tickCount > 0) {
                --this.lifeTicks;
                if (this.lifeTicks <= 14) {
                    this.level.broadcastEntityEvent(this, (byte) 7);
                }
                if (this.lifeTicks < 0) {
                    this.discard();
                }
            }

            if (this.getOwner() != null){
                if (this.getOwner() instanceof Mob){
                    if (this.needsConcentrate()) {
                        if (this.getOwner().hurtTime > 0 && this.tickCount < 10 && !this.getOwner().isDeadOrDying()) {
                            this.lifeTicks = 14;
                            this.level.broadcastEntityEvent(this, (byte) 7);
                        }
                    }
                }
            }

            if (this.isInLava()){
                this.level.broadcastEntityEvent(this, (byte)6);
                this.discard();
            }
        }

    }

public void handleEntityEvent(byte pId) {
        super.handleEntityEvent(pId);
        if (pId == 5) {
            if (!this.isSilent()) {
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), ModSounds.WRAITH_FIRE.get(), this.getSoundSource(), 1.0F, 1.0F, false);
            }
        }
        if (pId == 6){
            if (!this.isSilent()) {
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.FIRE_EXTINGUISH, this.getSoundSource(), 1.0F, 1.0F, false);
            }
        }
        if (pId == 7){
            if (!this.isDying()) {
                this.lifeTicks = 14;
                this.setDying(true);
            }
        }
        if (pId == 8){
            if (!this.isSilent()) {
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), ModSounds.REDSTONE_FIRE_PROJECTILE.get(), this.getSoundSource(), 0.3F, 1.3F, false);
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), ModSounds.FIRE_PROJECTILE_FLY.get(), this.getSoundSource(), 0.3F, 1.3F, false);
            }
        }

    }

