@Override
	public void update() {
		super.update();

		if (suckingCooldown > 0) {
			suckingCooldown--;
			//markDirty();
		}

		if (!((BlockCraftingPlate) getBlockType()).testStructure(getWorld(), getPos()).isEmpty()) return;

		if (getStructurePos() != getPos()) {
			setStructurePos(getPos());
			markDirty();
		}

		if (!ManaManager.isManaFull(getWizardryCap())) {
			for (BlockPos relative : poses) {
				BlockPos target = getPos().add(relative);
				TileEntity tile = world.getTileEntity(target);
				if (tile instanceof TileOrbHolder) {
					if (!((TileOrbHolder) tile).isPartOfStructure() || ((TileOrbHolder) tile).canGiveToOutside() || !((TileOrbHolder) tile).canSuckFromOutside()) {
						((TileOrbHolder) tile).setStructurePos(getPos());
						((TileOrbHolder) tile).setCanGiveToOutside(false);
						((TileOrbHolder) tile).setCanSuckFromOutside(true);
						tile.markDirty();
					}
				}
			}
		}

		if (!world.isRemote) {
			for (EntityItem entityItem : world.getEntitiesWithinAABB(EntityItem.class, new AxisAlignedBB(pos))) {
				if (entityItem.getItem().isEmpty()) continue;
				if (hasInput()) break;

				if (!isInventoryEmpty() && CraftingPlateRecipeManager.doesRecipeExistForItem(entityItem.getItem())) {

					ItemStack stack = entityItem.getItem().copy();
					stack.setCount(1);
					entityItem.getItem().shrink(1);

					input.getHandler().insertItem(0, stack, false);

					PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(getPos(), stack), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

				} else if (!(CraftingPlateRecipeManager.doesRecipeExistForItem(entityItem.getItem()))) {

					ItemStack stack = entityItem.getItem().copy();
					stack.setCount(1);

					ItemStack left = ItemHandlerHelper.insertItem(realInventory.getHandler(), stack, false);
					if (left.isEmpty()) {
						entityItem.getItem().shrink(1);
						PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(getPos(), stack), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
					}
				}
			}
		}

		boolean done = CraftingPlateRecipeManager.tick(world, pos, getInput(), realInventory.getHandler(), this::suckMana);
		if (done) {
			ItemStack inputStack = input.getHandler().extractItem(0, 1, false);
			if (!inputStack.isEmpty()) {
				output.getHandler().insertItem(0, inputStack, false);
				for (int i = 0; i < realInventory.getHandler().getSlots(); i++)
					realInventory.getHandler().setStackInSlot(i, ItemStack.EMPTY);
				PacketHandler.NETWORK.sendToAllAround(new PacketClearCraftingPlate(pos), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 128));
			}
			markDirty();
		}
	}

public static boolean tick(World world, BlockPos pos, ItemStack input, ItemStackHandler inventoryHandler, Function<IManaCapability, Double> consumeMana) {
		ICraftingPlateRecipe recipe = null;

		for (ICraftingPlateRecipe search : recipes) {
			if (search.doesRecipeExistInWorld(world, pos) || search.doesRecipeExistForItem(input)) {
				recipe = search;
				break;
			}
		}
		if (recipe == null) return false;

		if (!recipe.isDone(world, pos, input)) {
			recipe.tick(world, pos, input, inventoryHandler, consumeMana);
		} else {
			recipe.complete(world, pos, input, inventoryHandler);
			return true;
		}
		return false;
	}

@Override
	public boolean isDone(World world, BlockPos pos, ItemStack stack) {
		return ManaManager.isManaFull(stack);
	}

@Override
	public void tick(World world, BlockPos pos, ItemStack input, ItemStackHandler inventoryHandler, Function<IManaCapability, Double> consumeMana) {
		if (!ManaManager.isManaFull(input)) {
			ManaManager.forObject(input).addMana(consumeMana.apply(ManaCapabilityProvider.getCap(input))).close();
		}
	}

@Override
	public void complete(World world, BlockPos pos, ItemStack input, ItemStackHandler inventoryHandler) {
		ArrayList<ItemStack> stacks = new ArrayList<>();

		for (int i = 0; i < inventoryHandler.getSlots(); i++) {
			if (!inventoryHandler.getStackInSlot(i).isEmpty()) {
				stacks.add(inventoryHandler.getStackInSlot(i));
				inventoryHandler.setStackInSlot(i, ItemStack.EMPTY);
			}
		}

		// Process spellData multipliers based on nacre quality
		double pearlMultiplier = 1;
		if (input.getItem() instanceof INacreProduct) {
			float purity = ((INacreProduct) input.getItem()).getQuality(input);
			if (purity >= 1f) pearlMultiplier = ConfigValues.perfectPearlMultiplier * purity;
			else if (purity <= ConfigValues.damagedPearlMultiplier)
				pearlMultiplier = ConfigValues.damagedPearlMultiplier;
			else {
				double base = purity - 1;
				pearlMultiplier = 1 - (base * base * base * base);
			}
		}

		SpellBuilder builder = new SpellBuilder(stacks, pearlMultiplier);

		NBTTagList list = new NBTTagList();
		for (SpellRing spellRing : builder.getSpell()) {
			list.appendTag(spellRing.serializeNBT());
		}

		SpellUtils.infuseSpell(input, list);

		//markDirty();

		PacketHandler.NETWORK.sendToAllAround(new PacketExplode(new Vec3d(pos).add(0.5, 0.5, 0.5), Color.CYAN, Color.BLUE, 2, 2, 500, 300, 20, true),
				new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

		world.playSound(null, pos, ModSounds.BASS_BOOM, SoundCategory.BLOCKS, 1f, (float) RandUtil.nextDouble(1, 1.5));

		List<Entity> entityList = world.getEntitiesWithinAABBExcludingEntity(null, new AxisAlignedBB(pos).grow(32, 32, 32));
		for (Entity entity1 : entityList) {
			double dist = entity1.getDistance(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5);
			final double upperMag = 3;
			final double scale = 0.8;
			double mag = upperMag * (scale * dist / (-scale * dist - 1) + 1);
			Vec3d dir = entity1.getPositionVector().subtract(new Vec3d(pos).add(0.5, 0.5, 0.5)).normalize().scale(mag);

			entity1.motionX = (dir.x);
			entity1.motionY = (dir.y);
			entity1.motionZ = (dir.z);
			entity1.fallDistance = 0;
			entity1.velocityChanged = true;

			if (entity1 instanceof EntityPlayerMP)
				((EntityPlayerMP) entity1).connection.sendPacket(new SPacketEntityVelocity(entity1));
		}
	}

@Override
	public boolean isDone(World world, BlockPos pos, ItemStack stack) {
		TileEntity tileEntity = world.getTileEntity(pos.offset(EnumFacing.UP));
		if (!(tileEntity instanceof TileJar)) return false;
		TileJar jar = (TileJar) tileEntity;

		return ManaManager.isManaFull(jar.fairy.handler);
	}

@Override
	public void tick(World world, BlockPos pos, ItemStack input, ItemStackHandler inventoryHandler, Function<IManaCapability, Double> consumeMana) {
		TileEntity tileEntity = world.getTileEntity(pos.offset(EnumFacing.UP));
		if (!(tileEntity instanceof TileJar)) return;
		TileJar jar = (TileJar) tileEntity;

		if (jar.fairy != null
				&& jar.fairy.infusedSpell.isEmpty()
				&& !jar.fairy.isDepressed
				&& !ManaManager.isManaFull(jar.fairy.handler)) {
			ManaManager.forObject(jar.fairy.handler).addMana(consumeMana.apply(jar.fairy.handler)).close();
			jar.markDirty();
		}
	}

